# ─── expansion logic ─────────────────────────────────────────────────────────

def expand_html(html: str) -> str:
    """Expand existing lesson HTML content to ~3x size."""
    parts = []
    parts.append(html)

    # Add exercises section if not present
    if "<h3>Practice" not in html and "<h3>Exercise" not in html and "Practice" not in html:
        parts.append("<h3>Practice Exercises:</h3><ol>")
        parts.append("<li>Modify the code example to handle edge cases</li>")
        parts.append("<li>Write a test case for the main functionality</li>")
        parts.append("<li>Refactor the code to improve performance</li>")
        parts.append("</ol>")

    # Add key concepts summary if not present
    if "Key Concepts" not in html and "key points" not in html:
        parts.append("<h3>Key Takeaways:</h3><ul>")
        parts.append("<li>Understanding the fundamental concepts is crucial for advanced topics</li>")
        parts.append("<li>Always consider edge cases and error handling</li>")
        parts.append("<li>Practice with real-world examples to solidify knowledge</li>")
        parts.append("</ul>")

    return "".join(parts)


def expand_lesson_content(lesson: dict) -> dict:
    """Expand an existing lesson's HTML content."""
    expanded = lesson.copy()
    expanded["html"] = expand_html(lesson["html"])
    return expanded


def expand_course(course_dir: Path, new_lessons: list):
    """Expand a course's lessons and add new ones."""
    main_path = course_dir / "main.json"
    with open(main_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    # Expand existing lessons
    data["lessons"] = [expand_lesson_content(l) for l in data["lessons"]]

    # Add new lessons
    data["lessons"].extend(new_lessons)

    # Write back
    with open(main_path, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)

    print(f"  Expanded: {len(data['lessons'])} lessons total")


