NEW_LESSONS["full_stack_php_development"] = [
    {
        "title": "Lesson 8: Testing with PHPUnit",
        "html": "<h2>Comprehensive Testing in PHP</h2><p>PHPUnit is the standard testing framework for PHP. Supports unit tests, integration tests, and TDD.</p><h3>Test Case:</h3><pre><code>&lt;?php\nuse PHPUnit\\Framework\\TestCase;\n\nclass UserTest extends TestCase {\n    private UserRepository $repo;\n\n    protected function setUp(): void {\n        $this->repo = new UserRepository(new MemoryDatabase());\n    }\n\n    public function testCreateUser(): void {\n        $user = $this->repo->create([\n            'name' => 'Alice',\n            'email' => 'alice@example.com'\n        ]);\n        $this-&gt;assertNotNull($user-&gt;getId());\n        $this-&gt;assertEquals('Alice', $user-&gt;getName());\n    }\n\n    public function testEmailValidation(): void {\n        $this-&gt;expectException(\\InvalidArgumentException::class);\n        $this-&gt;repo-&gt;create(['name' => 'Bob', 'email' => 'invalid']);\n    }\n\n    /** @dataProvider userProvider */\n    public function testValidation(string $name, string $email, bool $expected): void {\n        $this-&gt;assertEquals($expected, (new UserValidator())-&gt;isValid($name, $email));\n    }\n\n    public function userProvider(): array {\n        return [\n            ['Alice', 'alice@ex.com', true],\n            ['', 'alice@ex.com', false],\n            ['Alice', 'invalid', false],\n        ];\n    }\n}</code></pre><h3>Practice Exercises:</h3><ol><li>Write integration tests for the database layer</li><li>Create a test suite with fixtures and groups</li><li>Implement mock objects for external services</li></ol><h3>Key Takeaways:</h3><ul><li>setUp() runs before each test method</li><li>Data providers supply multiple test inputs</li><li>Mocks isolate unit tests from dependencies</li></ul>"
    },
    {
        "title": "Lesson 9: Queues & Job Processing",
        "html": "<h2>Background Job Processing in Laravel</h2><p>Job queues handle time-consuming tasks asynchronously, improving response times.</p><h3>Job Class:</h3><pre><code>&lt;?php\nnamespace App\\Jobs;\n\nuse App\\Models\\User;\nuse App\\Notifications\\WelcomeEmail;\nuse Illuminate\\Contracts\\Queue\\ShouldQueue;\nuse Illuminate\\Queue\\InteractsWithQueue;\nuse Illuminate\\Bus\\Queueable;\n\nclass SendWelcomeEmail implements ShouldQueue\n{\n    use Dispatchable, InteractsWithQueue, Queueable;\n\n    public $timeout = 120;\n    public $tries = 3;\n    public $backoff = [10, 30, 60];\n\n    public function __construct(private User $user) {}\n\n    public function handle(): void\n    {\n        try {\n            $this-&gt;user-&gt;notify(new WelcomeEmail($this-&gt;user));\n        } catch (\\Exception $e) {\n            $this-&gt;release(30);\n        }\n    }\n\n    public function failed(\\Throwable $e): void\n    {\n        Log::error('Job failed: ' . $e-&gt;getMessage());\n    }\n}</code></pre><h3>Dispatching:</h3><pre><code>SendWelcomeEmail::dispatch($user);\nProcessOrder::dispatch($order)-&gt;delay(now()-&gt;addMinutes(15));\nGenerateReport::dispatch($report)-&gt;onQueue('reports');</code></pre><h3>Practice Exercises:</h3><ol><li>Create a report generation job with batch processing</li><li>Implement job middleware for rate limiting</li><li>Monitor queue worker with Horizon</li></ol><h3>Key Takeaways:</h3><ul><li>Jobs run outside the HTTP request lifecycle</li><li>Retries handle transient failures automatically</li><li>Queues can be prioritized by importance</li></ul>"
    },
    {
        "title": "Lesson 10: Caching with Redis",
        "html": "<h2>Performance Optimization with Redis</h2><p>Redis provides in-memory storage for caching, sessions, and real-time features.</p><h3>Cache Usage:</h3><pre><code>use Illuminate\\Support\\Facades\\Cache;\n\n// Store\nCache::put('user_'.$id, $user, 3600);\nCache::put('settings', $settings, now()-&gt;addDays(7));\n\n// Retrieve\n$user = Cache::get('user_'.$id);\n\n// Remember (cache + auto-update)\n$users = Cache::remember('active_users', 300, function () {\n    return User::where('active', true)-&gt;get();\n});\n\n// Tags for group invalidation\nCache::tags(['users'])-&gt;put('user_'.$id, $user, 3600);\nCache::tags('users')-&gt;flush();</code></pre><h3>Redis Advanced:</h3><pre><code>use Illuminate\\Support\\Facades\\Redis;\n\n// Rate limiting\n$attempts = Redis::incr('rate_limit:'.$ip);\nif ($attempts === 1) Redis::expire('rate_limit:'.$ip, 60);\n\n// Leaderboard (sorted sets)\nRedis::zadd('scores', $score, $userId);\n$top10 = Redis::zrevrange('scores', 0, 9, 'WITHSCORES');\n\n// Pub/Sub\nRedis::publish('notifications', json_encode(['message' => 'New update']));</code></pre><h3>Practice Exercises:</h3><ol><li>Implement a full-page cache middleware</li><li>Build a real-time leaderboard with sorted sets</li><li>Use Redis for session storage across multiple servers</li></ol><h3>Key Takeaways:</h3><ul><li>Redis reduces database load significantly</li><li>Cache tags enable group invalidation</li><li>Sorted sets are perfect for leaderboards</li></ul>"
    },
    {
        "title": "Lesson 11: Event Broadcasting & WebSockets",
        "html": "<h2>Real-Time Events with Laravel Echo</h2><p>WebSockets enable real-time features like notifications and live updates.</p><h3>Event Broadcasting:</h3><pre><code>class OrderStatusUpdated implements ShouldBroadcast\n{\n    use Dispatchable, InteractsWithSockets;\n\n    public function __construct(public Order $order) {}\n\n    public function broadcastOn(): array\n    {\n        return [\n            new Channel('orders.'.$this-&gt;order-&gt;user_id),\n            new PrivateChannel('admin.notifications'),\n        ];\n    }\n\n    public function broadcastWith(): array\n    {\n        return ['order_id' =&gt; $this-&gt;order-&gt;id, 'status' =&gt; $this-&gt;order-&gt;status];\n    }\n}</code></pre><h3>Client-Side:</h3><pre><code>import Echo from 'laravel-echo';\nimport Pusher from 'pusher-js';\n\nwindow.Echo = new Echo({ broadcaster: 'pusher', key: '...', cluster: '...' });\n\nEcho.channel('orders.' + userId)\n    .listen('.order.status.updated', (e) =&gt; updateOrderStatus(e.order_id, e.status));\n\nEcho.join('chat.' + roomId)\n    .here((users) =&gt; console.log('Online:', users))\n    .joining((user) =&gt; console.log('Joined:', user))\n    .leaving((user) =&gt; console.log('Left:', user));</code></pre><h3>Practice Exercises:</h3><ol><li>Build a real-time chat application</li><li>Implement presence channels for online status</li><li>Add WebSocket notifications for background jobs</li></ol><h3>Key Takeaways:</h3><ul><li>Broadcasting pushes events to connected clients</li><li>Presence channels track user online status</li><li>Private channels require authorization</li></ul>"
    },
    {
        "title": "Lesson 12: API Resources & Transformation",
        "html": "<h2>Controlling API Response Format</h2><p>API resources transform models into JSON, controlling which data is exposed.</p><h3>UserResource:</h3><pre><code>class UserResource extends JsonResource\n{\n    public function toArray(Request $request): array\n    {\n        return [\n            'id' =&gt; $this-&gt;id,\n            'name' =&gt; $this-&gt;name,\n            'email' =&gt; $this-&gt;email,\n            'avatar' =&gt; $this-&gt;avatar_url,\n            'joined_at' =&gt; $this-&gt;created_at-&gt;toISOString(),\n            'stats' =&gt; [\n                'posts_count' =&gt; $this-&gt;posts_count,\n                'followers_count' =&gt; $this-&gt;followers_count,\n            ],\n            $this-&gt;mergeWhen($request-&gt;user()?->isAdmin(), [\n                'is_admin' =&gt; $this-&gt;is_admin,\n            ]),\n        ];\n    }\n\n    public function with(Request $request): array\n    {\n        return ['meta' =&gt; ['api_version' =&gt; '1.0', 'timestamp' =&gt; now()-&gt;toISOString()]];\n    }\n}</code></pre><h3>Resource Collection:</h3><pre><code>class UserCollection extends ResourceCollection\n{\n    public $collects = UserResource::class;\n\n    public function toArray(Request $request): array\n    {\n        return [\n            'data' =&gt; $this-&gt;collection,\n            'pagination' =&gt; [\n                'total' =&gt; $this-&gt;total(),\n                'per_page' =&gt; $this-&gt;perPage(),\n                'current_page' =&gt; $this-&gt;currentPage(),\n                'total_pages' =&gt; $this-&gt;lastPage(),\n            ],\n        ];\n    }\n}</code></pre><h3>Practice Exercises:</h3><ol><li>Create nested resources for related models</li><li>Implement conditional attribute inclusion</li><li>Build a sparse fieldsets feature</li></ol><h3>Key Takeaways:</h3><ul><li>Resources control response shape</li><li>mergeWhen conditionally includes fields</li><li>Collections handle pagination metadata</li></ul>"
    },
    {
        "title": "Lesson 13: Advanced Eloquent ORM",
        "html": "<h2>Eloquent Relationships & Performance</h2><p>Eloquent ORM makes database interactions intuitive. Master relationships and eager loading.</p><h3>Advanced Relationships:</h3><pre><code>class Post extends Model\n{\n    // Has-Many-Through\n    public function postComments(): HasManyThrough\n    {\n        return $this-&gt;through('user')-&gt;has('comments');\n    }\n\n    // Polymorphic\n    public function images(): MorphMany\n    {\n        return $this-&gt;morphMany(Image::class, 'imageable');\n    }\n\n    // Belongs-To-Many with pivot data\n    public function subscribers(): BelongsToMany\n    {\n        return $this-&gt;belongsToMany(User::class)-&gt;withPivot(['subscribed_at', 'notify'])-&gt;withTimestamps();\n    }\n\n    // Scopes\n    public function scopePublished($query) {\n        return $query-&gt;whereNotNull('published_at')-&gt;where('published_at', '&lt;=', now());\n    }\n}</code></pre><h3>Performance:</h3><pre><code>// Eager loading to avoid N+1\n$posts = Post::with(['user', 'comments.author', 'tags'])-&gt;published()-&gt;paginate(20);\n\n// Lazy eager loading\n$posts = Post::all();\nif ($includeComments) { $posts-&gt;load('comments'); }\n\n// Chunk for large datasets\nPost::chunk(100, function ($posts) { foreach ($posts as $post) { /* ... */ } });\n\n// Cursor pagination for infinite scroll\n$posts = Post::orderBy('id')-&gt;cursorPaginate(25);</code></pre><h3>Practice Exercises:</h3><ol><li>Set up a polymorphic comment system</li><li>Optimize a slow page with eager loading</li><li>Implement a global scope for multi-tenancy</li></ol><h3>Key Takeaways:</h3><ul><li>Eager loading eliminates N+1 queries</li><li>Polymorphic relationships handle multiple parent types</li><li>Cursor pagination scales better than offset pagination</li></ul>"
    },
    {
        "title": "Lesson 14: Form Requests & Validation",
        "html": "<h2>Advanced Validation Rules</h2><p>Form Requests encapsulate validation logic. Custom rules keep code clean.</p><h3>Form Request:</h3><pre><code>class StoreUserRequest extends FormRequest\n{\n    public function authorize(): bool\n    {\n        return $this-&gt;user()-&gt;can('create', User::class);\n    }\n\n    public function rules(): array\n    {\n        return [\n            'name' =&gt; ['required', 'string', 'min:2', 'max:255'],\n            'email' =&gt; ['required', 'email', Rule::unique('users')-&gt;ignore($this-&gt;user), 'max:255'],\n            'password' =&gt; ['required', 'string', 'min:8', 'confirmed',\n                'regex:/^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)/'],\n            'role' =&gt; ['required', Rule::in(['user', 'admin', 'moderator'])],\n            'avatar' =&gt; ['nullable', 'image', 'mimes:jpeg,png', 'max:2048'],\n        ];\n    }\n\n    public function messages(): array\n    {\n        return [\n            'name.required' =&gt; 'Please provide your full name.',\n            'password.regex' =&gt; 'Password needs uppercase, lowercase, and number.',\n        ];\n    }\n}</code></pre><h3>Custom Rule:</h3><pre><code>class CurrentPassword implements ValidationRule\n{\n    public function validate(string $attribute, mixed $value, Closure $fail): void\n    {\n        if (!Hash::check($value, auth()-&gt;user()-&gt;password)) {\n            $fail('The :attribute does not match your current password.');\n        }\n    }\n}</code></pre><h3>Practice Exercises:</h3><ol><li>Create a custom rule for phone number validation</li><li>Implement conditional validation rules</li><li>Build reusable rule classes for addresses</li></ol><h3>Key Takeaways:</h3><ul><li>Form Requests keep controllers clean</li><li>Custom rules are reusable across requests</li><li>Conditional rules adapt to the input</li></ul>"
    },
    {
        "title": "Lesson 15: File Storage & Media Library",
        "html": "<h2>File Management with Laravel</h2><p>Laravel's filesystem supports local, S3, and cloud storage with a unified API.</p><h3>File Upload:</h3><pre><code>class MediaController extends Controller\n{\n    public function upload(UploadRequest $request)\n    {\n        $file = $request-&gt;file('file');\n\n        $path = $file-&gt;storeAs(\n            'uploads/' . date('Y/m'),\n            uniqid() . '.' . $file-&gt;extension(),\n            's3'\n        );\n\n        // Generate thumbnail for images\n        if (str_starts_with($file-&gt;getMimeType(), 'image/')) {\n            $thumbnail = Image::make($file)-&gt;fit(300, 300)-&gt;encode();\n            Storage::disk('s3')-&gt;put('thumbnails/' . basename($path), $thumbnail);\n        }\n\n        $media = Media::create([\n            'filename' =&gt; basename($path),\n            'original_name' =&gt; $file-&gt;getClientOriginalName(),\n            'path' =&gt; $path,\n            'mime_type' =&gt; $file-&gt;getMimeType(),\n            'size' =&gt; $file-&gt;getSize(),\n            'user_id' =&gt; auth()-&gt;id(),\n        ]);\n\n        return response()-&gt;json($media, 201);\n    }\n}</code></pre><h3>Practice Exercises:</h3><ol><li>Build a media library with image optimization</li><li>Implement signed URLs for private files</li><li>Create a file versioning system</li></ol><h3>Key Takeaways:</h3><ul><li>Filesystem abstraction works with any storage provider</li><li>Image manipulation happens server-side</li><li>Thumbnails improve loading speed</li></ul>"
    }
]

