# ─── Main Execution ───────────────────────────────────────────────────────────

def expand_html(html: str) -> str:
    """Expand existing lesson HTML content to ~3x size by adding exercises and key concepts."""
    parts = [html]

    if "<h3>Practice" not in html and "Practice" not in html:
        parts.append("\n<h3>Practice Exercises:</h3><ol>"
            "<li>Modify the code example to handle edge cases</li>"
            "<li>Write a test case for the main functionality</li>"
            "<li>Refactor the code to improve performance or readability</li>"
            "</ol>")

    if "Key Takeaways" not in html and "key points" not in html:
        parts.append("\n<h3>Key Takeaways:</h3><ul>"
            "<li>Understanding the fundamental concepts is crucial for advanced topics</li>"
            "<li>Always consider edge cases and error handling in production code</li>"
            "<li>Practice with real-world examples to solidify your knowledge</li>"
            "</ul>")

    return "".join(parts)


def expand_course(course_dir: Path, new_lessons: list):
    """Expand a course's existing lessons and add new ones."""
    main_path = course_dir / "main.json"
    with open(main_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    expanded = []
    for lesson in data["lessons"]:
        lesson["html"] = expand_html(lesson["html"])
        expanded.append(lesson)

    for lesson in new_lessons:
        expanded.append(lesson)

    data["lessons"] = expanded

    with open(main_path, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)

    print(f"  Done: {len(expanded)} lessons total")


if __name__ == "__main__":
    print("Starting course expansion...")
    print(f"Courses with new lessons: {len(NEW_LESSONS)}")

    for course_name in sorted(NEW_LESSONS.keys()):
        course_dir = BASE / course_name
        if not course_dir.exists():
            print(f"  SKIP: {course_name} - directory not found")
            continue
        print(f"\nProcessing: {course_name}")
        expand_course(course_dir, NEW_LESSONS[course_name])

    print("\nAll courses expanded successfully!")
